        waypoints.append({'xyz': [xyz[0], xyz[1]-finger_offset*np.cos(pitch), xyz[2]-finger_offset+finger_offset*np.sin(pitch)], 'quat': [c,-s,s,c], 'grip': 0.0})
    return waypoints

